def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 2]
    rows = {}
    for r, c in points:
        rows.setdefault(r, []).append(c)
    # The row containing the horizontal pair is the spine; connect all marked points to it.
    spine = next(r for r, cols in rows.items() if len(cols) >= 2)
    endpoints = rows[spine]
    for c in range(min(endpoints), max(endpoints) + 1):
        if out[spine][c] == 0:
            out[spine][c] = 3
    for r, c in points:
        if r != spine:
            for rr in range(min(r, spine), max(r, spine) + 1):
                if out[rr][c] == 0:
                    out[rr][c] = 3
    return out

if __name__ == '__main__':
    test = [[0]*17 for _ in range(14)]
    for r,c in [(3,6),(6,4),(8,1),(8,12),(10,10),(12,8)]: test[r][c]=2
    for row in transform(test): print(*row)
